\begin{definition}[{\bf The residual mapping}]\label{def:res_maps}\em Given $\beta>0$ and a smoothing parameter $\eta>0$, for any $\x \in \mathbb{R}^n$ and an arbitrary vector $\tilde e \in \mathbb{R}^n$,
					let the residual mappings $G_{\eta,\beta}(\x)$ and $\tilde{G}_{\eta,\beta}(\x, {\tilde e})$ be defined as $G_{\eta,\beta}(\x)  \triangleq \beta {\left(\x - \Pi_{\Xscr}\left[\x - \tfrac{1}{\beta} \nabla_x {f_{\eta}(\x)}\right]\right)}$ and $\tilde{G}_{\eta,\beta}(\x, {\tilde e})  \triangleq \beta\left( \x - \Pi_{\Xscr}\left[\x - \tfrac{1}{\beta} ({\nabla_x f_{\eta}(\x)}+\tilde{e}) \right]\right)$, respectively.
					%\begin{align}
					%    G_{\eta,\beta}(\x) &\triangleq \beta {\left(\x - \Pi_{\Xscr}\left[\x - \tfrac{1}{\beta} \nabla_x {f_{\eta}(\x)}\right]\right)} \mbox{ and }\\
					%    \hspace{-0.05in}\tilde{G}_{\eta,\beta}(\x, {\tilde e}) &\triangleq \beta\left( \x - \Pi_{\Xscr}\left[\x - \tfrac{1}{\beta} ({\nabla_x f_{\eta}(\x)}+\tilde{e}) \right]\right). \hspace{-0.1in} \qed
					%\end{align}
				\end{definition}

\begin{algorithm}[hbt]
					\caption{\texttt{{VRG-ZO}}: Variance-reduced randomized zeroth-order {gradient} method}\label{algorithm:zo_nonconvex}
					%\begin{boxedminipage}{165mm}
					{   \begin{algorithmic}[1]
							\STATE\textbf{input:}  Given $\x_0 \in \Xscr$, stepsize $\gamma>0$, smoothing parameter $\eta>0$, mini-batch sequence $\{N_k\}$, and an integer $R_{\ell,K}$ randomly selected from $\{\ell\triangleq\lceil\lambda K\rceil ,\ldots,K\}$ using a discrete uniform distribution where $\lambda \in (0,1)$ and $K\geq 1$.
							\FOR {$k=0,1,\ldots,{K}-1$}
							\STATE   Generate a random {mini-}{batch $v_{j,k} \in \eta \mathbb{S}$ for $j=1,\ldots,N_k$}  
							% \STATE Generate a random {batch $\xi_{j,k}$ for $j=1,\ldots,N_k$}  
							\STATE  Compute $\{g_{\eta}(\x_k,v_{j,k},\xi_{j,k})\}_{j=1}^{N_k}$, where for all $j=1,\ldots,N_k$,\\ $g_{\eta}(\x_k,v_{j,k},\xi_{j,k}) :=\left(\tfrac{n}{\us{2}\eta}\right)\left({\f}(\x_k+ v_{j,k},\xi_{j,k}) - {\f}(\x_k- v_{j,k},\xi_{j,k})\right)\tfrac{v_{j,k}}{\left\|v_{j,k}\right\|}$ 
							\STATE   {Compute} mini-batch inexact {ZO} gradient. $
							g_{\eta,N_k}(\x_k) := \tfrac{\sum_{j=1}^{N_k}  g_{\eta}\left(\x_k,v_{j,k},\xi_{j,k}\right)}{N_k}$
							\STATE   {Update $\x_k$ as follows.}
							$\x_{k+1}:= \Pi_{\Xscr}\left[ \x_{k}-\gamma g_{\eta,N_k}(\x_k) \right]$
							\ENDFOR
							\STATE Return $\x_{R_{\ell,K}}$ 
					\end{algorithmic}}
					%\end{boxedminipage}
					% \vskip17.5pt
				\end{algorithm}

\begin{align*}
					g_{\eta}(\x_k,v_{j,k},\xi_{j,k}) \triangleq \left(\tfrac{n}{\eta}\right)\left({\f}(\x_k+ v_{j,k},\xi_{j,k}) - {\f}({\x_k-v_{j,k}},\xi_{j,k})\right)\tfrac{v_{j,k}}{\left\|v_{j,k}\right\|},
				\end{align*}

where $v_{j,k} \in \eta\mathbb{S}$.  {Intuitively, $g_{\eta}(\x_k,v_{j,k},\xi_{j,k})$ generates a gradient estimate by employing sampled function evaluations $\tilde{f}(\x_k{+v_{j,k}},\xi_{j,k})$ and $\tilde{f}(\x_k{-v_{j,k}},\xi_{j,k})$; in short, the zeroth-order oracle, given an $\x_k$ and a perturbation vector $v_{j,k}$, produces two evaluations, \fy{i.e.,}   
	$\tilde{f}(\x_k +v_{j,k},\xi_{j,k})$ and $\tilde{f}(\x_k-v_{j,k},\xi_{j,k})$.}
%\lm{We then employ a mini-batch approximation of this gradient estimate.} 
We formally define the stochastic errors emergent from the randomized scheme based on a mini-batch approximation.

\begin{definition}\label{def:stoch_errors} \em
					For all $k\geq 0,j=1,\ldots,N_k$, let 
					$\mathbf{e}_k\triangleq \tfrac{\sum_{j=1}^{N_k}\mathbf{e}_{j,k}}{N_k}$, %, $\bm{\theta}_k\triangleq \tfrac{\sum_{j=1}^{N_k}\bm{\theta}_{j,k}}{N_k}$, 
					\begin{align}
						e_{j,k} & \triangleq {g_{\eta}(\x_k,v_{j,k},\xi_{j,k}) -\nabla f_\eta(\x_k)}, \ \mbox{and } {\mathbf{e}_{j,k}  \triangleq g_{\eta}(\x_k,\vv_{j,k},\bxi_{j,k})}-\nabla f_\eta(\x_k)\label{def:stoch_errors1}. \mbox{$\ \Box$}
						%\\ \theta_{j,k } & \triangleq g_{\eta}(\x_k,v_{j,k},\xi_{j,k}) -\nabla {\f}_\eta(\x_k,\xi_{j,k}), \mbox{ and } {\bm{\theta}_{j,k}  \triangleq g_{\eta}(\x_k,\vv,\bxi_{\lm{j}}) -\nabla {\f}_\eta(\x_k,\bxi_{\lm{j}})}.\label{def:stoch_errors2}
						%&\delta_{j,k} \triangleq  g_{\eta}(\x_k,v_{j,k},\xi_{j,k}) -  g_{\eta}(\x_k,v_{j,k},\xi_{j,k}),\label{def:stoch_errors3}
					\end{align}
				\end{definition}

\begin{align}\label{eqn:history}
					\mathcal{F}_0 \triangleq \{x_0\},\quad 
					\mathcal{F}_k \triangleq \mathcal{F}_{k-1} \, \bigcup \, \left\{ \, \bigcup_{j=1}^{N_{k-1}}\, \{\xi_{j,k-1}, v_{j,k-1}\} \, \right\}, \qquad \hbox{for } k \geq 1.
				\end{align}

\begin{assumption}[{\bf Independence}]\label{assum:random_vars}\em
					Random samples $\xi_{j,k}$, $v_{j,k}$ are generated independent of each other for all $k\geq 0$ and $1\leq j \leq N_k$.
				\end{assumption}

