\begin{theorem}[{\bf Rate and complexity statements for \texttt{VRG-ZO}}]\label{thm:vr-rb-zo}%Alg.~\ref{algorithm:zo_nonconvex}
					\em
					Consider Algorithm \ref{algorithm:zo_nonconvex}. Let Assumptions~\ref{ass-1} and \ref{assum:random_vars} hold.  Let $a > 0$ be an arbitrary scalar.

					{\noindent {\bf  (a)  [Constant step]}} Let $\gamma_k:=\gamma<{\frac{\eta}{\sqrt{n} L_0}}$ and $N_k:=  \lceil  a \sqrt{n}L_0 (k+1) \rceil$ for $k \geq 0$.  %\farz{{\bf TODO:} $a$ cannot be zero, because we use $a^{-1}$ in the proof. I changed $a \geq 0$ to $a >0$. With this change, the addition of 1 in $N_k:= n L_0 \lceil 1+a(k+1) \rceil$ seems unnecessary because $\lceil a(k+1) \rceil \geq 1$ anyway. So I removed 1 in $N_k:= n L_0 \lceil 1+a(k+1) \rceil$. I also moved $L_0$ inside the ceiling term because it could be non-integer. Please check.}

					\noindent {\bf{(a-i)}} For $K> \tfrac{2}{1-\lambda}$ with $\ell\triangleq  \lceil \lambda K\rceil$, we have
					\begin{align}\label{eqn:GBound_constant_gamma}
						\mathbb{E}\left[ \|G_{\eta,1/\gamma} (\x_{R_{\ell,K}})\|^2\right] \leq %\left(\left( 1-\tfrac{\lm{\sqrt{n}}L_0\gamma_{\lm{0}}}{\eta}\right) \tfrac{\gamma}{4}(1-\lambda)K \right)^{-1}\\
						\tfrac{\left(\mathbb{E}\left[f(\x_{\ell})\right] -f^* +2L_0\eta+ \left( {16 \sqrt{n}} \sqrt{2\pi} L_0 \right)(0.5-\ln(\lambda)) {{a^{-1}}}\gamma\right)}{\left(\left( 1-\tfrac{{\sqrt{n}}L_0\gamma}{\eta}\right) \tfrac{\gamma}{4}(1-\lambda)K \right)}.
					\end{align}
					\noindent {\bf{(a-ii)}} Let $\gamma= {\tfrac{\eta}{2{\sqrt{n}}L_0}}$,  $\epsilon>0$, and $K_{\epsilon}$ satisfy $ \mathbb{E}\left[ \|G_{\eta,1/\gamma} (\x_{R_{\ell,K_{\epsilon}}})\|\right]   \leq \epsilon$.  Then the following hold.  {{(a-ii-1)}} The total no. of projection steps is $K_{\epsilon}=\mathcal{O}\left({n^{1/2}}{(L_0\eta^{-1} +L_0^2)} \epsilon^{-2}\right)$.%\farz{{\bf TODO:} I don't think $\eta^{-1}$ will appear in the complexity result here. $\gamma$ seems to cancel out from denominator in $\tfrac{\gamma}{4}(K-\ell)$ and numerator in $\gamma\sum_{k=\ell}^{K-1} \tfrac{\lm{1}}{N_k}$ and there won't remain any $\eta^{-1}$. Please check. }

					\noindent {{(a-ii-2)}} The overall sample complexity is $\mathcal{O}\left({n^{3/2}(L_0^3\eta^{-2}+L_0^5)} \epsilon^{-4}\right)$.

					\noindent {\bf  (b)  [Diminishing step]} Let  $\gamma_k = \tfrac{\gamma_0}{\sqrt{k+1}}$ and {$N_k:=  {\lceil a{\sqrt{n}} L_0{\sqrt{k+1}} \rceil }$}, where {$\gamma_0<{{\eta}{{\sqrt{n}} L_0}}$}. 
				 {\bf{(b-i)}}  For $K> \tfrac{2}{1-\lambda}$ with $\ell\triangleq  \lceil \lambda K\rceil$, we have
					\begin{align}\label{eqn:GBound_diminish_gamma}
						\mathbb{E}\left[ \|G_{\eta,1/\gamma_0} (\x_{R_{\ell,K}})\|^2\right] \leq \tfrac{\left(\mathbb{E}\left[f(\x_{\ell})\right] -f^* +2L_0\eta+  \left({16  \sqrt{2\pi} L_0\sqrt{n}}\right)  (0.5-\ln(\lambda))\lm{a^{-1}}\gamma_0\right)}{\left(\left( 1-\tfrac{{\sqrt{n}} L_0\gamma_0}{\eta}\right) {\tfrac{\gamma_0}{2}}(1-\sqrt{\lambda})\sqrt{K}\right)}.
					\end{align}
					\noindent {\bf{(b-ii)}}  Let $\epsilon>0$ and $K_{\epsilon}$ be such that $ \mathbb{E}\left[ \|G_{\eta,1/{\gamma_0}} (\x_{R_{\ell,K_\epsilon}})\|\right]   \leq \epsilon$. Then the following hold. 
					 {{(b-ii-1)}} The total number of projection steps is  $K_{\epsilon}=\mathcal{O}\left({n(L_0^2\eta^{-2} +L_0^4)} \epsilon^{-4}\right).$ {{(b-ii-2)}} The total sample complexity is $\mathcal{O}\left({n^{2}(L_0^4\eta^{-3}+L_0^7)} \epsilon^{-6}\right)$.
				\end{theorem}

