\begin{lemma}[L\'{e}vy concentration on $ \mathbb{S}^n $~{\cite[Prop. 3.11 and Example 3.12]{Wainwright2019}}]
					\label{lemma:levy-concentration}\em
					Let ${h}: \mathbb{R}^n \to \mathbb{R}$ be $L$-Lipschitz and $\tilde{\vv}$ be uniformly distributed on {$\mathbb{S}$}. Then 
					\begin{align}
						\mathbb{P}\left[\, \left|\, h(\tilde{\vv}) - \mathbb{E}[h(\tilde{\vv})]\, \right|\, \geq \, \alpha \, \right] &\, \leq \, 2 \sqrt{2\pi} e^{-\frac{n \alpha^2}{8L^2}}.
					\end{align}
				\end{lemma}

\begin{lemma}[{\bf Properties of spherical smoothing}] \label{lemma:props_local_smoothing}\em Suppose $h:\mathbb{R}^n \mapsto \mathbb{R}$ is {a continuous function and its smoothed counterpart $h_{\eta}$ is defined as \eqref{def-smooth}, where $\eta>0$ is a given scalar}. Then the following hold for any $\x, \y \in {\cal X}$.

\begin{enumerate}
						\item[ (i)] $h_{\eta}$ is $C^1$ over $\Xscr$ and $\nabla_{\x} h_{\eta}(\x) = \left(\tfrac{n}{2\eta}\right) \mathbb{E}_{\vv \in \eta \mathbb{S}} \left[\left(h(\x+\vv)-h(\x-\vv)\right) \tfrac{\vv}{\|\vv\|}\right]. $ 
					\end{enumerate}
					%    \begin{align}
						%        \nabla_{\x} h_{\eta}(\x) = \left(\tfrac{n}{\eta}\right) \mathbb{E}_{\vv \in \eta \mathbb{S}} \left[\us{h(\x+\vv) \tfrac{\vv}{\|\vv\|}}\right] \quad \forall \x \in \Xscr. 
						%    \end{align}
Suppose $h \in C^{0,0}(\Xscr_{\eta})$ with parameter $L_0$. For any $\x, \y \in \Xscr$,  the following hold. 

					\begin{enumerate}
						\item[ (ii)] $| h_{\eta}(\x)-h_{\eta}(\y) | \leq L_0 \|\x-\y\|.$  (iii) $| h_{\eta}(\x) - h(\x)| \leq L_0 \eta.$ 

						\item[ (iv)] $\| \nabla_{\x} h_{\eta}(\x) -\nabla_{\x} h_{\eta}(\y)\| \leq {
							\tfrac{L_0 \sqrt{n}}{\eta}}\|\x-\y\|.$
						%    \item[(v)] If $h$ is convex {and $h \in C^{0,0}(\Xscr_{\eta})$ with parameter $L_0$}, then $h_{\eta}$ is convex and satisfies the following for any $\x \in \Xscr$. 
						%        \begin{align}
							%                h(\x) \leq h_{\eta}(\x) \leq h(\x) + \eta L_0.
							%            \end{align} 
						% \item[(vi)] $h_{\eta} \in C^{0,0}$.  \us{Prove//cite} FY: This seems redundant. It is already shown in (ii).
						%  \item[(iv)] If \fy{$\eta>0$, then $ h_{\eta}(\x)$ is continuously differentiable and} $\nabla h_{\eta}(\x)$ is defined as $$ \nabla h_{\eta}(\x) \triangleq \tfrac{1}{\kappa} \int_{\fy{\mathbb{R}^n}} \tfrac{f(\x+\eta u) - f(\x)}{\eta} e^{-\frac{\|u\|^2}{2}} Bu du. $$ \fy{Moreover}, $h_{\eta} \in C^{1,1}$ and $L_1(h_{\eta}) = \tfrac{\sqrt{n}}{\eta} L_0(h).$  
						%    \item[(vi)] If $h$ is convex {and $h \in C^{0,0}(\Xscr_{\eta})$ with parameter $L_0$}, then $\nabla_x h_{\eta}(\x) \in \partial_{\epsilon} h(\x)$ where {$\epsilon \triangleq \eta L_0$}.

						%\item[(vii)] If $h \in C^{0,0}$ and $\eta > 0$, then $h_{\eta} \in C^{1,1}$ and $L_1(f_{\eta}) = \tfrac{\sqrt{n} L_0(f)}{\eta}.$ 
						%     \us{Modify for spherical/Prove/Cite} FY: I think the version we use in the paper is already shown in (iv)

						%    \item[(vii)] If {$h \in C^{1,1}(\Xscr_{\eta})$} with constant {$L_1$}, then $$\|\nabla_x h_{\eta}(\x)-\nabla_x h(\x) \| \leq {\eta L_1 n}.$$

						\item [(v)] {Suppose $h \in C^{0,0}(\Xscr_{\eta})$ with parameter $L_0$ {and} 
							$g_{\eta}(\x,\vv)  \triangleq \left(\tfrac{n(h(\x+\vv) - h(\x-\vv))\vv}{2\eta\|\vv\|}\right)$
							for $\vv \in \eta\mathbb{S}$.  Then for} any $\x \in \Xscr$, we have that ${\mathbb{E}_{\vv \in \eta \mathbb{S}}}[{\|{g_\eta}(\x,\vv)\|^2}] \leq 16\sqrt{2\pi}L_0^2 n$. $\hfill \Box$ 
					\end{enumerate}
				\end{lemma}

\begin{proof}
					{(i) By Stoke's theorem and spherical symmetry of $\vv$, we have that 
						\begin{align*}
							\nabla_{\x} h_{\eta}(\x)& = \tfrac{n}{\eta} \mathbb{E}_{\vv \in \eta \mathbb{S}} \ \left[ \tfrac{h(\x+\vv) \vv }{\|\vv\|} \right] = 
							\tfrac{n}{2\eta} \mathbb{E}_{\vv \in \eta \mathbb{S}} \ \left[ \tfrac{(h(\x+\vv)+h(\x+\vv)) \vv }{\|\vv\|} \right] \\
							& = \tfrac{n}{2\eta} \mathbb{E}_{\vv \in \eta \mathbb{S}} \ \left[ \tfrac{(h(\x+\vv)) \vv }{\|\vv\|}+\tfrac{(h(\x+\vv)) \vv }{\|\vv\|} \right] = 
							\tfrac{n}{2\eta} \mathbb{E}_{\vv \in \eta \mathbb{S}} \ \left[ \tfrac{(h(\x+\vv)) \vv }{\|\vv\|}+\tfrac{(h(\x-\vv)) (-\vv) }{\|\vv\|} \right] \\
							& = \tfrac{n}{2\eta} \mathbb{E}_{\vv \in \eta \mathbb{S}} \ \left[ \tfrac{((h(\x+\vv))-(h(\x-\vv)) \vv) }{\|\vv\|} \right]. 
						\end{align*}
						(ii,iii) follow akin to ~\cite[Lemma 1]{CSY2021MPEC}. 
						(iv)
Recall from~\cite[Prop. 2.2]{lin2022} that $\|
\nabla_{\x} h_{\eta}(\x) -\nabla_{\x}
h_{\eta}(\y)\| \leq \tfrac{C_n
L_0}{\eta}\|\x-\y\|,$ for $n\geq 1$, where
$C_n \triangleq
\left(\tfrac{2}{\pi}\right)^{p_n}
\tfrac{n!!}{(n-1)!!}$ and $p_n = 1$ if $n$
is even, and $p_n =0$ otherwise. It suffices to show that $C_n \le 1$ for $n \ge 1$. For $n \ge
0$, let $w_n$ denote the Wallis'
integrals~\cite{spivak2006calculus}, given as
$w_n = \int_{0}^{\pi/2}\sin^n(u)du$. Then we
have $w_n =\left(\tfrac{n-1}{n}\right)w_{n-2}$ for $n \geq
2$ where $w_0=\tfrac{\pi}{2}$ and $w_1=1$
(cf.~\cite[Ch. 19]{spivak2006calculus}). This
implies (via mathematical induction) that
$w_n =
\left(\tfrac{\pi}{2}\right)\tfrac{(n-1)!!}{n!!}$
for even $n$, while $w_n =
\tfrac{(n-1)!!}{n!!}$ for odd $n$. Let us
define $v_n \,\triangleq \, (n+1)w_n w_{n+1}$ for $n\geq 0$.
We obtain $v_n =
(n+1)\left(\tfrac{\pi}{2}\right)
\tfrac{(n-1)!!}{n!!}\tfrac{n!!}{(n+1)!!} =
\tfrac{\pi}{2}$, implying that $v_n =
\tfrac{\pi}{2}$ for all $n\geq 0$. Recall
that from~\cite{spivak2006calculus} we have
$w_{n+1} < w_n$ for all $n\geq 0$. Thus we
obtain $\tfrac{\pi}{2} = v_n  =(n+1)w_n
w_{n+1} < (n+1)w_n^2$ for all $n\geq 0$, i.e., $w_n < \tfrac{\pi}{2(n+1)}$ for $n \ge 0$.  Note
that $C_1 =1$. Suppose $n \geq 2$. We have
$C_n= \tfrac{1}{w_n} <
\sqrt{\tfrac{2(n+1)}{\pi}} =
\sqrt{\tfrac{2(1+1/n)}{\pi}} \sqrt{n} \leq
\sqrt{\tfrac{2(1+1/2)}{\pi}} \sqrt{n} \leq
0.98 \sqrt{n} $. This implies that $C_n  \leq
1$ for all $n\geq 1$.} {(v) We have that}
\begin{align*}
							\mathbb{E}\left[ \|g_{\eta}(\x,\vv)\|^2 \right] & \le 
							\tfrac{n^2}{4\eta^2} \mathbb{E}\left[ \|\tfrac{(h(\x+\vv)-h(\x-\vv))\vv}{\|\vv\|}\|^2 \right] \le 
							\tfrac{n^2}{4\eta^2} \mathbb{E}\left[  (h(\x+\vv)-h(\x-\vv))^2 \tfrac{\|\vv\|^2}{\|\vv\|^2} \right] \\
							& \le 
							\tfrac{n^2}{4\eta^2} \mathbb{E}\left[ \left(h(\x+\vv)-\mathbb{E}\left[h(\x+\vv)\right] + \mathbb{E}\left[ h(\x+\vv)\right]-h(\x-\vv)\right)^2  \right]. 
						\end{align*}
						But $\mathbb{E}\left[ h(\x+\vv)\right] = \mathbb{E}\left[ h(\x-\vv)\right]$ by spherical symmetry. Consequently, 
						\begin{align*}
							\mathbb{E}\left[ \|g_{\eta}(\x,\vv)\|^2 \right] & \le 
							\tfrac{n^2}{4\eta^2} \mathbb{E}\left[  \left(h(\x+\vv)-\mathbb{E}\left[h(\x+\vv)\right] + \mathbb{E}\left[ h(\x-\vv)\right]-h(\x-\vv)\right)^2  \right] \\
							& \le \tfrac{2n^2}{4\eta^2} \mathbb{E}\left[ \left|(h(\x+\vv)-\mathbb{E}\left[h(\x+\vv)\right]\right|^2  + \left|\mathbb{E}\left[ h(\x-\vv)\right]-h(\x-\vv))\right|^2 \right]. 
						\end{align*}
						Then by invoking L\'{e}vy's inequality (cf. Lemma~\ref{lemma:levy-concentration}), we have that 
						\begin{align*}
							\mathbb{E}\left[ |(h(\x+\vv)-\mathbb{E}\left[h(\x+\vv)\right]|^2 \right] \le 2\sqrt{2\pi}\int_0^{\infty} e^{-\alpha n}{8 \eta^2 L_0^2} d\alpha = \tfrac{16\sqrt{2\pi} \eta^2 L_0^2}{n}. 
						\end{align*}
